buy_code:
매수 = False

if 데이터길이 >= {min_len}:
    if {b1_start} <= 시분초 < {b1_end}:
        if {b1_cap_lo} <= 시가총액 < {b1_cap_hi}:
            if (등락율 >= {b1_rate_min} and 등락율 <= {b1_rate_max}
                and 당일거래대금 >= {b1_day_money_min}
                and 분당거래대금 >= {b1_min_money_min}
                and 분당거래대금 >= 분당거래대금평균({b1_money_avg_win}, 1) * {b1_money_burst}
                and 분당매수수량 >= 누적분당매수수량({b1_buyqty_win}) / {b1_buyqty_win} * {b1_buyqty_accel}
                and 누적분당매수수량({b1_cum_fast_win}) >= 누적분당매수수량({b1_cum_slow_win}) * {b1_cum_share}
                and 현재가 >= 이동평균({b1_ma_win}, 1) * {b1_ma_mult}):
                매수 = True
    elif {b2_start} <= 시분초 < {b2_end}:
        if {b2_cap_lo} <= 시가총액 < {b2_cap_hi}:
            if (등락율 >= {b2_rate_min} and 등락율 <= {b2_rate_max}
                and 당일거래대금 >= {b2_day_money_min}
                and 분당거래대금 >= {b2_min_money_min}
                and 분당거래대금 >= 분당거래대금평균({b2_money_avg_win}, 1) * {b2_money_burst}
                and 분당매수수량 >= 누적분당매수수량({b2_buyqty_win}) / {b2_buyqty_win} * {b2_buyqty_accel}
                and 누적분당매수수량({b2_cum_fast_win}) >= 누적분당매수수량({b2_cum_slow_win}) * {b2_cum_share}
                and 현재가 >= 이동평균({b2_ma_win}, 1) * {b2_ma_mult}):
                매수 = True

if 매수:
    self.Buy()

sell_code:
매도 = False

if 수익률 >= {take_profit}:
    매도 = True
elif 수익률 <= -{stop_loss}:
    매도 = True
elif 최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap}:
    매도 = True
elif 보유시간 >= {max_hold_sec}:
    매도 = True

if 매도:
    self.Sell()
